<?php require 'config.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify();$id=(int)($_POST['id']??0);$q=(int)($_POST['qty']??0);if(isset($_SESSION['cart'][$id])){if($q<=0)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=min(20,$q);}go('cart.php');}$cart=$_SESSION['cart']??[];$items=[];$total=0;if($cart){$s=$db->prepare('SELECT * FROM products WHERE active=1 AND id IN ('.implode(',',array_fill(0,count($cart),'?')).')');$s->execute(array_keys($cart));$items=$s->fetchAll();foreach($items as $p)$total+=$p['price']*$cart[$p['id']];}head('Cart');?><h1>Your cart 🛒</h1><?php foreach($items as $p):?><article class="card"><h3><?=h($p['name'])?></h3><p>ETB <?=h($p['price'])?></p><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="id" value="<?=h($p['id'])?>"><label>Quantity (0 removes)<input type="number" min="0" max="20" name="qty" value="<?=h($cart[$p['id']])?>"></label><button>Update</button></form></article><?php endforeach;?><h2>Total ETB <?=h(number_format($total,2))?></h2><?php if($total>0):?><a class="btn" href="checkout.php">Checkout</a><?php else:?><a href="index.php">Browse menu</a><?php endif;foot();?>
